// Released source: KS/SRC/ks/PhotoFrontEnd.cpp and PhotoFrontEnd.h.
class FEMultiMenu {
    char layout[0x15c];
public:
    virtual ~FEMultiMenu();
};

class PhotoSelectMenu {
    char layout[0x74];
public:
    virtual ~PhotoSelectMenu();
};

class PhotoSaveMenu {
    char layout[0x74];
public:
    virtual ~PhotoSaveMenu();
};

class PhotoDevelopMenu {
    char layout[0x74];
public:
    virtual ~PhotoDevelopMenu();
};

class PhotoFrontEnd : public FEMultiMenu {
    PhotoSelectMenu *selectMenu;
    PhotoSaveMenu *saveMenu;
    PhotoDevelopMenu *develMenu;
public:
    virtual ~PhotoFrontEnd();
};

PhotoFrontEnd::~PhotoFrontEnd()
{
    // Unlike menu entries, submenus have to be manually deleted.
    delete selectMenu;
    delete saveMenu;
    delete develMenu;
}
